BEGIN;
CREATE OR REPLACE FUNCTION dukaflow_current_business_id() RETURNS BIGINT LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('app.business_id',true),'')::BIGINT $$;
CREATE OR REPLACE FUNCTION dukaflow_current_branch_id() RETURNS BIGINT LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('app.branch_id',true),'')::BIGINT $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['products','customers','suppliers','sales','sale_items','debts','debt_payments','purchases','purchase_items','stock_movements','sale_returns','sale_return_items','cash_registers','cash_movements','supplier_payments','notifications','loyalty_accounts','loyalty_transactions','customer_notes','audit_logs','approval_requests','dashboard_widget_preferences','api_idempotency_keys','ai_conversations','ai_messages','ai_memories','offline_mutations','purchase_returns','purchase_return_items'] LOOP EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS branch_id BIGINT',t); END LOOP; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['products','customers','suppliers','sales','sale_items','debts','debt_payments','purchases','purchase_items','stock_movements','sale_returns','sale_return_items','cash_registers','cash_movements','supplier_payments','notifications','loyalty_accounts','loyalty_transactions','customer_notes','audit_logs','approval_requests','dashboard_widget_preferences','api_idempotency_keys','ai_conversations','ai_messages','ai_memories','offline_mutations','purchase_returns','purchase_return_items'] LOOP EXECUTE format('UPDATE %I x SET branch_id=b.id FROM branches b WHERE x.business_id=b.business_id AND b.code=''MAIN'' AND x.branch_id IS NULL',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION dukaflow_assign_branch_id() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.branch_id IS NULL THEN NEW.branch_id:=dukaflow_current_branch_id(); END IF; IF NEW.branch_id IS NULL THEN SELECT id INTO NEW.branch_id FROM branches WHERE business_id=NEW.business_id AND code='MAIN' LIMIT 1; END IF; IF NEW.branch_id IS NULL THEN RAISE EXCEPTION 'Branch required'; END IF; RETURN NEW; END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['products','customers','suppliers','sales','sale_items','debts','debt_payments','purchases','purchase_items','stock_movements','sale_returns','sale_return_items','cash_registers','cash_movements','supplier_payments','notifications','loyalty_accounts','loyalty_transactions','customer_notes','audit_logs','approval_requests','dashboard_widget_preferences','api_idempotency_keys','ai_conversations','ai_messages','ai_memories','offline_mutations','purchase_returns','purchase_return_items'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS dukaflow_assign_branch_%I ON %I',t,t); EXECUTE format('CREATE TRIGGER dukaflow_assign_branch_%I BEFORE INSERT ON %I FOR EACH ROW EXECUTE FUNCTION dukaflow_assign_branch_id()',t,t); EXECUTE format('ALTER TABLE %I ALTER COLUMN branch_id SET NOT NULL',t); EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_business_branch ON %I(business_id,branch_id)',t,t); EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS dukaflow_branch_isolation ON %I',t); EXECUTE format('CREATE POLICY dukaflow_branch_isolation ON %I USING(business_id=dukaflow_current_business_id() AND branch_id=dukaflow_current_branch_id()) WITH CHECK(business_id=dukaflow_current_business_id() AND branch_id=dukaflow_current_branch_id())',t); END LOOP; END $$;
COMMIT;
